export const SAMPLE_COPY=Object.fromEntries(Object.entries(translations).map(([l,values])=>[l,Object.fromEntries(keys.map((k,i)=>[k,values[i]]))]));
const requests={ko:'물과 앞접시를 부탁드려요.',en:'Could we have water and small plates?',vi:'Cho tôi xin nước và đĩa nhỏ.',zh:'请给我们水和小盘子。',ja:'お水と取り皿をお願いします。',km:'សូមទឹក និងចានតូច។',id:'Boleh minta air dan piring kecil?',lo:'ຂໍນ້ຳ ແລະຈານນ້ອຍ.',hi:'कृपया पानी और छोटी प्लेट दें।'};
for(const [lang,copy] of Object.entries(SAMPLE_COPY))copy.sampleStaffRequest=requests[lang];
const units={ko:'인분',en:'servings',vi:'phần',zh:'份',ja:'人前',km:'ចំណែក',id:'porsi',lo:'ທີ່',hi:'परोस'};
const dateAt=(now,days=0)=>{const d=new Date(now);d.setDate(d.getDate()+days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
export function createOwnerSample(lang='ko',now=new Date()){
 const c=SAMPLE_COPY[lang]||SAMPLE_COPY.ko,at=new Date(now).toISOString(),items=structuredClone(MENU).map(x=>({...x,available:true}));
 const visit=(n,table,language)=>({id:'sample-visit-'+n,table,lang:language,at,nickname:'Sample '+n,consent:false,cart:{},games:{},coupons:[],points:0,pointLedger:[],messages:[],chatCount:0,thread:[{id:'sample-question-'+n,at,seq:1,role:'user',key:n===2?'qComplaint':'qSpicy'},{id:'sample-answer-'+n,at,seq:2,role:'assistant',key:n===2?'replyComplaint':'replySpicy'}]});
 const sessions=[visit(1,3,lang),visit(2,7,'en'),visit(3,2,'vi'),visit(4,5,lang)];
 const order=(n,cart,status,payment)=>{const v=sessions[n-1],lines=Object.entries(cart).map(([id,quantity])=>{const item=items.find(i=>i.id===id);return {itemId:id,name:structuredClone(item.name),quantity,unitPrice:item.price};});return {id:'sample-order-'+n,requestId:'sample-order-request-'+n,number:100+n,sessionId:v.id,table:n%2===0?null:v.table,fulfillment:sampleFulfillment(n,v.table),lang:v.lang,at,lines,total:lines.reduce((sum,l)=>sum+l.quantity*l.unitPrice,0),status,payment};};
 return {version:2,sampleVersion:SAMPLE_VERSION,sampleRoutingVersion:1,sampleCreated:dateAt(now),store:{name:'주모 · JUMO',address:c.sampleAddress,country:'VN',phone:'',email:'jumo@example.com',website:'https://isaacweb007.github.io/jumo-joseon-hiphop-book/?lang=ko#cover',hours:'17:00–01:00',perVisit:15,perDay:100,media:[{id:'sample-exterior',name:'Jumo exterior · concept',kind:'venue',type:'image/jpeg',url:'assets/exterior.jpg'},{id:'sample-interior',name:'Jumo interior · concept',kind:'venue',type:'image/jpeg',url:'assets/interior.jpg'},{id:'sample-menu',name:'Jumo jeon · concept',kind:'menu',type:'image/jpeg',url:'assets/jeon.jpg'}]},items,menu:{},sessions,activeSession:null,orders:[order(1,{m04:1,m05:1},'completed','paid'),order(2,{m01:2,m12:1},'preparing','unpaid'),order(3,{m16:2,m17:1},'accepted','paid'),order(4,{m04:1,m15:1},'pending','unpaid')],reservations:[{id:'sample-booking-1',number:1,sessionId:sessions[0].id,table:3,lang,requestId:'sample-booking-request-1',date:dateAt(now),time:'19:00',partySize:4,name:'Sample A',status:'confirmed',at},{id:'sample-booking-2',number:2,sessionId:sessions[1].id,table:7,lang:'en',requestId:'sample-booking-request-2',date:dateAt(now,1),time:'18:30',partySize:2,name:'Sample B',status:'pending',at},{id:'sample-booking-3',number:3,sessionId:sessions[2].id,table:2,lang:'vi',requestId:'sample-booking-request-3',date:dateAt(now,1),time:'20:00',partySize:6,name:'Sample C',status:'pending',at}],events:[{id:'sample-complaint-1',type:'complaint',sessionId:sessions[1].id,detail:{questionKey:'qComplaint',question:'My food is taking too long',lang:'en'},reviewed:false,at},{id:'sample-staff-1',type:'eventStaff',sessionId:sessions[3].id,detail:{questionKey:'sampleStaffRequest'},reviewed:false,at}],manager:{profileName:'Jumo',stage:'ready',completed:true,messages:[{id:'sample-welcome',at,seq:1,role:'assistant',key:'sampleWelcome',card:'sample-home'}]},inventory:[{id:'sample-stock-1',name:items[0].name[lang]||items[0].name.ko,quantity:18,unit:units[lang]||units.en,at},{id:'sample-stock-2',name:items[1].name[lang]||items[1].name.ko,quantity:12,unit:units[lang]||units.en,at}],staffTasks:[{id:'sample-task-1',title:c.sampleTask1,assignee:'Kitchen',done:false,at},{id:'sample-task-2',title:c.sampleTask2,assignee:'Floor',done:false,at}]};
}

function sampleFulfillment(n,table){return n%2===0?{channel:'online',name:'Sample '+n,address:'DEMO ONLY · District 1, Ho Chi Minh City · Room '+(100+n),phone:'+1 202-555-01'+String(n).padStart(2,'0')}:{channel:'dine-in',table};}
export function upgradeOwnerSample(state){const s=structuredClone(state);for(const o of s.orders){const n=Number(o.id.match(/^sample-order-([1-4])$/)?.[1]);if(n&&!o.fulfillment){o.fulfillment=sampleFulfillment(n,o.table);if(o.fulfillment.channel==='online')o.table=null;}}s.sampleRoutingVersion=1;return s;}
